10	+it("observes installed current Event replay minimum admission across sources", async () => {
11	+  // The full suite executes this same witness locally; only externally bound artifacts
12	+  // can supply installed attribution. A declared source string alone proves no provenance.
13	+  const entryOverride = process.env.BDP_TRANSACTIONAL_INSTALLED_ENTRY;
