40	+    dirtyPaths: execFileSync("git", ["diff", "--name-only", "HEAD"], {
41	+      cwd: root,
42	+      encoding: "utf8",
43	+    })
44	+      .trim()
45	+      .split("\n")
46	+      .filter(Boolean),
47	+  };
48	+  const controller = new AbortController();
49	+  const started = performance.now(),
50	+    workEnd = started + 45000;
51	+  const directory = mkdtempSync(path.join(tmpdir(), "bdp-event-replay-minimum-installed-"));
52	+  const token = randomBytes(32).toString("base64url");
53	+  function safeFailureMessage(error: unknown): string {
