64	+    credentials: [{ token, principal: "writer", canMutate: true }],
65	+  };
66	+  const seedKey = "event-replay-minimum-three-operations-v1";
67	+  const seedBytes = Buffer.from(
68	+    JSON.stringify({
69	+      operations: [
70	+        ...["a", "b"].map((id) => ({ operation: "createBead", id: `beads/${id}`, type, properties: { n: 0 } })),
71	+        { operation: "createLink", id: "links/l", type: `${scope}types/link`, source: "beads/a", target: "beads/b", properties: { n: 0 } },
72	+      ],
73	+    }),
74	+  );
75	+  type Handle = Awaited<ReturnType<typeof launchInstalledTransaction>>;
76	+  type Session = {
77	+    ordinal: number;
78	+    create: boolean;
79	+    state: "launching" | "owned" | "unknown-no-handle";
80	+    handle?: Handle;
81	+    pid?: number | undefined;
