84	+    exit?: { code: number | null; signal: NodeJS.Signals | null };
85	+    closing?: Promise<void>;
86	+    drained?: Promise<void>;
87	+    closeEvent?: { code: number | null; signal: NodeJS.Signals | null };
88	+    closed: boolean;
89	+    stopUnknown: boolean;
90	+  };
91	+  const sessions: Session[] = [];
92	+  const failures: { phase: string; error: unknown }[] = [];
