113	+  function track<T>(promise: Promise<T>): Promise<T> {
114	+    pending.add(promise);
115	+    // Both handlers are attached before any race; even a late failure is observed.
116	+    void promise.then(
117	+      () => pending.delete(promise),
118	+      () => pending.delete(promise),
119	+    );
120	+    return promise;
121	+  }
122	+  function closeStream(): Promise<void> {
123	+    if (!stream) return Promise.resolve();
124	+    const owned = stream;
125	+    owned.closing ??= track(
126	+      owned.recorder.close().then(() => {
127	+        owned.drained = true;
128	+      }),
