226	+  try {
227	+    const ajv = new Ajv2020({ allErrors: true, strict: true });
228	+    ajv.addFormat("uri", { type: "string", validate: isJsonSchemaUri });
229	+    ajv.addFormat("date-time", { type: "string", validate: isJsonSchemaDateTime });
230	+    const bundle = JSON.parse(readFileSync(path.join(root, "schemas/bdp-v0.schema.json"), "utf8"));
