349	+    }
350	+    phase = "launch";
351	+    const session = await launch(true);
352	+    const handle = session.handle;
353	+    if (!handle) throw new Error("missing returned child handle");
354	+    const address = new URL(handle.ready.listenUrl as string);
355	+    const execute = createRawHttpExchangeExecutor(
356	+      { transport: "plain", host: address.hostname, port: Number(address.port) },
