927	+    async advance() {
928	+      const result = await service.submit({ carrier: { kind: "batch" }, body: JSON.stringify({ operations: [create("c")] }), key: "event-replay-advance", authorization: { kind: "authorized", principal: "p" }, receiving: { acceptsJson: true, maximumOperations: 1 } });
929	+      expect(result).toMatchObject({ kind: "receipt", receipt: { status: "completed", requiredPosition: "pos-2" } }); commits++;
930	+    },
931	+    async cleanup(failures: unknown[]) {
932	+      controller.abort(); latch.resolve(); now = 2;
933	+      try { if (operation) await replayBound(operation, "Event operation drain timeout"); } catch (error) { failures.push(error); }
934	+      try { await replayBound(close(), "Event service close timeout"); const result = await replayBound(closed, "Event closed observation timeout"); if (!result.ok) failures.push(result.error); } catch (error) { failures.push(error); }
935	+    },
936	+    counts: () => ({ serviceCalls, ownerAttempts: attempts.length, baselineCalls: 1, waits, clockCalls, commits, ownerCloseCalls }),
937	+  };
938	+}
939	+it.each(["scope-json", "bead-json", "link-json", "scope-sse", "bead-sse", "link-sse"] as const)(
940	+  "captures current Event replay minimum once across owner entries: %s",
941	+  async (label) => {
942	+    const { TransactionMinimumFailure } = await import("./transaction-consistency.js");
943	+    const [kind, transport] = label.split("-") as [keyof typeof replaySources, "json" | "sse"];
944	+    const f = await replayMinimumService(kind, transport), failures: unknown[] = [];
945	+    const captured = { ...f.minimum };
946	+    try {
947	+      const observed = f.start(); await f.waitEntered();
948	+      Object.assign(f.minimum, { scopeEpoch: "mutated-epoch", authorizationView: "mutated-view", minimumPosition: "pos-1" });
949	+      await f.advance(); f.setNow(2); f.release();
950	+      const result = await replayBound(observed, "Event retry result timeout");
951	+      expect(result.ok).toBe(false); if (result.ok) throw new Error("opaque replay admitted");
952	+      expect(result.error).toBeInstanceOf(TransactionMinimumFailure);
953	+      expect(result.error).toMatchObject({ reason: "catch-up-timeout", context: { scopeEpoch: captured.scopeEpoch, authorizationView: captured.authorizationView, scopePosition: "pos-2" } });
954	+      expect(f.attempts.map((a) => a.minimum)).toEqual([captured, captured]);
955	+      expect(f.attempts.map((a) => a.after)).toEqual([f.after, f.after]);
956	+      expect(f.attempts.map((a) => a.intent)).toEqual(["current-event", "current-event"]);
957	+      expect(f.attempts.map((a) => a.context?.scopePosition)).toEqual(["pos-1", "pos-2"]);

