1	/** Bounded observation of a deliberately nonterminal raw HTTP/1.1 stream.
2	 * Separate from the finite exact executor: closing is not a completed response. */
3	import { connect } from "node:net";
4	export function recordRawSse(options: {
5	  dial: string;
6	  host: string;
7	  target: string;
8	  headers: readonly [string, string][];
9	  method?: "GET" | "HEAD";
10	  signal: AbortSignal;
11	  timeoutMs?: number;
12	}) {
13	  const started = performance.now();
14	  const ready = Promise.withResolvers<void>();
15	  const closed = Promise.withResolvers<void>();
16	  void ready.promise.catch(() => {});
17	  const address = new URL(options.dial);
18	  const socket = connect({ host: address.hostname, port: Number(address.port) });
19	  const chunks: Buffer[] = [];
20	  let total = 0,
21	    status = 0,
22	    headers: Record<string, string> = {},
23	    body = "",
24	    failure: unknown;
25	  const subscribers = new Set<() => void>();
26	  const abort = () =>
27	    socket.destroy(
28	      options.signal.reason instanceof Error
29	        ? options.signal.reason
30	        : new Error("SSE observation aborted"),
31	    );
32	  const timer = setTimeout(
33	    () => socket.destroy(new Error("SSE observation deadline")),
34	    options.timeoutMs ?? 25000,
35	  );
36	  options.signal.addEventListener("abort", abort, { once: true });
37	  socket.once("connect", () => {
38	    if (options.signal.aborted) {
39	      abort();
40	      return;
41	    }
42	    const lines: readonly (readonly [string, string])[] = [
43	      ["Host", options.host],
44	      ["Connection", "close"],
45	      ...options.headers,
46	    ];
47	    if (lines.some(([k, v]) => /[\r\n]/.test(k + v)) || /[\r\n ]/.test(options.target)) {
48	      socket.destroy(new Error("invalid raw request fixture"));
49	      return;
50	    }
51	    socket.write(
52	      `${options.method ?? "GET"} ${options.target} HTTP/1.1\r\n${lines.map(([k, v]) => `${k}: ${v}`).join("\r\n")}\r\n\r\n`,
53	    );
54	  });
55	  socket.on("data", (chunk: Buffer) => {
56	    total += chunk.length;
57	    if (total > 2 * 1024 * 1024) {
58	      socket.destroy(new Error("SSE observation wire bound"));
59	      return;
60	    }
61	    chunks.push(Buffer.from(chunk));
62	    try {
63	      const wire = Buffer.concat(chunks);
64	      const end = wire.indexOf("\r\n\r\n");
65	      if (end < 0) {
66	        if (wire.length > 16384) throw new Error("SSE header bound");
67	        return;
68	      }
69	      if (end > 16384) throw new Error("SSE header bound");
70	      const lines = wire.subarray(0, end).toString("latin1").split("\r\n");
71	      status = Number(lines.shift()?.split(" ")[1]);
72	      headers = Object.fromEntries(
73	        lines.map((line) => {
74	          const colon = line.indexOf(":");
75	          return [line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim()];
76	        }),
