103	export function parseTransactionEventCursor(
104	  value: string,
105	  context?: TransactionReadContext,
106	): {
107	  position: number;
108	  ordinal: number;
109	  epoch: string;
110	  view: string;
111	  source: string;
112	} {
113	  const match = value.length <= 256 ? cursor.exec(value) : null;
114	  if (!match || !ordinal.test(match[5] ?? ""))
115	    throw new TransactionEventParameterError(undefined, context);
